var i=`0303-flija`;var t=`world-0303`;var n=`XK`;var o=`southern-europe`;var r=4;var l=143;var s={en:`Flija`,ua:`Флія`};var u={en:`A traditional Kosovo dish made with all-purpose flour, chicken egg, heavy cream, sour cream. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Косово. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, вершки високої жирності, сметана. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 17 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 17 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:17,i:[[`all-purpose-flour`,380,`g`],[`water`,180,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`heavy-cream`,350,`ml`],[`sour-cream`,200,`g`],[`unsalted-butter`,120,`g`]]},{en:`Build alternating layers of thin batter sheets and warm cream, briefly grilling each layer as in traditional flija; use a home oven grill and rotate the pan carefully.`,ua:`Збирайте чергуючи тонкі шари тіста й теплої вершкової заливки, підрум’янюючи кожен шар під верхнім нагрівом, як у традиційній флії; обережно повертайте форму.`,t:[`layered-assembly`],m:25,i:[]},{en:`Bake in a preheated 180°C oven for about 95 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 95 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:95,i:[]}];var g={slug:i,id:t,country:`XK`,region:o,servings:4,minutes:143,title:s,text:u,steps:d};export{n as country,g as default,t as id,l as minutes,o as region,r as servings,i as slug,d as steps,u as text,s as title};